<template>
  <!-- Бренд-блок: фирменный «Лист» из брендбука, залитый аэрофото речной долины.
       Во всю ширину экрана, без боковых полей — линия уходит за оба края.
       Слоган убран: раньше он занимал правую треть кадра (x 1198…1430) и держал
       фото обрезанным на x=1176, из-за чего «Лист» не доходил до края. -->
  <section ref="root" class="bs-section">
    <svg
      class="bs-art"
      :viewBox="`0 0 ${VB_W} ${VB_H}`"
      preserveAspectRatio="xMidYMid meet"
      role="img"
      :aria-label="ARIA"
    >
      <defs>
        <!-- Форма «Листа» вырезает фотографию -->
        <clipPath id="bs-clip" clipPathUnits="userSpaceOnUse">
          <path :d="LEAF_D" />
        </clipPath>
        <!-- Шторка: сдвигая её ширину по скроллу, заливаем «Лист» слева направо -->
        <clipPath id="bs-wipe" clipPathUnits="userSpaceOnUse">
          <rect ref="wipe" x="0" :y="-PAD" :width="VB_W + 2" :height="VB_H + PAD * 2" />
        </clipPath>
      </defs>

      <!-- Контур виден всегда: до прихода шторки блок не выглядит пустым -->
      <path class="bs-leaf-base" :d="LEAF_D" />

      <g clip-path="url(#bs-clip)">
        <g clip-path="url(#bs-wipe)">
          <image
            ref="photo"
            class="bs-photo"
            href="/images/brand-landscape.jpg"
            :x="-PAD"
            :y="-PAD"
            :width="VB_W + PAD * 2"
            :height="VB_H + PAD * 2"
            preserveAspectRatio="xMidYMid slice"
          />
        </g>
      </g>
    </svg>
  </section>
</template>

<script setup>
import { ref, onMounted, onUnmounted } from 'vue'

// Габариты пути «Листа» (getBBox: 1277 × 661.26) — viewBox повторяет их вплотную,
// поэтому при width:100% фигура упирается в оба края экрана без полей.
const VB_W = 1277
const VB_H = 662
// Запас кадра вокруг viewBox: из него берётся ход параллакса, чтобы при сдвиге
// фото не оголялся край маски.
const PAD = 80

const LEAF_D = "M1277 41.7171C1261.29 41.7831 1245.34 43.5367 1229.4 47.0761C1220.65 49.0245 1212.37 52.3407 1204.1 55.6543C1196.85 58.5584 1189.61 61.4607 1182.06 63.439C1187.68 64.2945 1191.86 64.9608 1195.29 65.5076C1202.06 66.5871 1205.93 67.2022 1212.24 67.8977C1234.7 70.3848 1256.54 76.2027 1277 85.0787V129.953C1161.21 65.9877 1045.44 147.655 1075.72 281.618C1079.86 299.986 1086.56 316.111 1095.23 330.672H1095.14C1144.85 444.546 1093.79 583.228 972.856 638.302C853.271 692.763 708.739 647.665 647.951 531.118C625.988 489.002 618.934 443.269 617.423 396.682C537.322 400.982 447.949 379.479 394.127 320.408C348.309 270.116 328.693 202.279 334.009 134.62L373.087 141.152C373.355 145.319 373.586 149.491 373.816 153.662V153.669C374.748 170.556 375.681 187.438 379.158 204.062C402.268 314.657 511.141 364.139 616.189 357.318C616.144 347.328 616.326 336.699 616.51 325.941V325.92C616.788 309.678 617.071 293.144 616.589 278.074C615.477 243.208 613.43 208.32 601.576 175.148C566.011 75.8339 463.41 24.2259 361.076 47.0761C352.376 49.0245 344.15 52.3407 335.93 55.6543C328.725 58.5583 321.524 61.4606 314.014 63.4389C319.603 64.2945 323.757 64.9608 327.168 65.5075C333.903 66.587 337.742 67.2022 344.017 67.8977C392.659 73.3148 438.344 94.5372 473.375 128.734C495.218 150.046 508.17 177.423 521.092 204.737L521.095 204.742C527.474 218.226 533.846 231.695 541.278 244.411C545.187 251.089 549.663 257.253 554.13 263.405L554.131 263.408C558.432 269.331 562.726 275.243 566.501 281.596L562.641 286.302C544.737 287.885 529.29 276.068 516.39 264.877C497.519 248.5 486.741 227.982 475.832 207.217C462.017 180.92 447.992 154.226 417.058 135.043C299.155 61.9229 177.449 144.295 208.298 281.619C212.421 299.987 219.079 316.111 227.698 330.672H227.606C277.025 444.546 226.267 583.228 106.044 638.302C71.8889 653.949 35.6866 661.377 0 661.255L1.82339e-06 619.541C16.0022 619.562 32.2676 617.811 48.5262 614.18C57.2266 612.232 65.4532 608.916 73.6739 605.602C80.8784 602.698 88.0792 599.796 95.59 597.817C90.0021 596.962 85.8487 596.297 82.4381 595.75L82.4326 595.749C75.6989 594.67 71.8594 594.054 65.5855 593.359C42.8119 590.822 20.687 584.821 3.74205e-06 575.647L5.70986e-06 530.628C115.508 595.838 231.503 514.069 201.304 379.639C197.181 361.27 190.525 345.146 181.905 330.584H181.996C132.577 216.71 183.337 78.0283 303.56 22.9545C422.441 -31.5064 566.123 13.5929 626.554 130.139C648.389 172.259 655.402 217.994 656.904 264.586C737.538 260.232 827.56 281.721 881.752 340.848C927.841 391.14 947.574 458.978 942.227 526.636L902.917 520.105C902.647 515.938 902.414 511.767 902.183 507.597V507.59C901.245 490.703 900.307 473.82 896.809 457.195C873.563 346.601 764.045 297.117 658.376 303.939C658.421 313.933 658.238 324.568 658.053 335.33V335.341C657.774 351.582 657.49 368.114 657.974 383.182C659.093 418.048 661.151 452.937 673.075 486.108C708.85 585.422 812.059 637.03 914.998 614.18C923.75 612.232 932.025 608.916 940.295 605.602C947.542 602.698 954.786 599.796 962.341 597.817C956.72 596.962 952.542 596.297 949.111 595.75L949.105 595.749C942.332 594.67 938.47 594.054 932.158 593.359C883.228 587.941 837.273 566.719 802.035 532.522C780.063 511.21 767.035 483.834 754.036 456.519C747.618 443.034 741.207 429.563 733.73 416.845C729.797 410.166 725.294 404.002 720.8 397.849C716.474 391.926 712.155 386.013 708.358 379.661L712.241 374.954C730.251 373.372 745.789 385.19 758.766 396.381C777.748 412.758 788.591 433.275 799.565 454.039C813.461 480.336 827.568 507.03 858.684 526.214C977.285 599.334 1099.71 516.961 1068.68 379.637C1064.53 361.269 1057.84 345.145 1049.17 330.584H1049.26C999.547 216.71 1050.61 78.0284 1171.54 22.9546C1205.51 7.4838 1241.49 0.04718 1277 7.1397e-05V41.7171Z"
const ARIA = 'Связь. Синергия опыта и технологий'

const root = ref(null)
const photo = ref(null)
const wipe = ref(null)
let raf = 0

const clamp01 = (v) => Math.min(1, Math.max(0, v))
const smoothstep = (a, b, x) => {
  const t = clamp01((x - a) / (b - a))
  return t * t * (3 - 2 * t)
}

// Прогресс считаем от живого rect — без ScrollTrigger и пинов, поэтому эффект
// не может «устареть» после поздних сдвигов вёрстки (прелоадер, догрузка медиа).
const update = () => {
  raf = 0
  const el = root.value
  const w = wipe.value
  const img = photo.value
  if (!el || !w || !img) return

  const r = el.getBoundingClientRect()
  // 0 — верх блока только показался снизу; 1 — низ ушёл за верх экрана
  const p = clamp01((window.innerHeight - r.top) / (window.innerHeight + r.height))

  // Шторка: фото заливает «Лист» слева направо в первой половине прохода
  w.setAttribute('width', String(((VB_W + 2) * smoothstep(0.10, 0.60, p)).toFixed(1)))

  // Параллакс: кадр внутри маски едет медленнее страницы
  img.setAttribute('y', String((-PAD + (p - 0.5) * 2 * PAD * 0.6).toFixed(1)))
}

const onScroll = () => {
  if (raf) return
  raf = requestAnimationFrame(update)
}

onMounted(() => {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    // Без анимации: «Лист» сразу залит целиком
    wipe.value?.setAttribute('width', String(VB_W + 2))
    return
  }
  window.addEventListener('scroll', onScroll, { passive: true })
  window.addEventListener('resize', onScroll, { passive: true })
  update()
})

onUnmounted(() => {
  if (raf) cancelAnimationFrame(raf)
  window.removeEventListener('scroll', onScroll)
  window.removeEventListener('resize', onScroll)
})
</script>

<style scoped>
.bs-section {
  position: relative;
  background: #ffffff;
  padding: clamp(2rem, 5vh, 4rem) 0;
  overflow: hidden;
}

/* Без max-width и боковых паддингов — блок идёт от края до края */
.bs-art {
  display: block;
  width: 100%;
  height: auto;
}

.bs-leaf-base { fill: #eef3f4; }
.bs-photo { will-change: transform; }
</style>
